import hashlib
import math

class BloomFilter:
    """
    A Bloom filter implementation to efficiently test whether an element is a member of a set
    with a certain probability of false positives. The size of the bit array and the number of
    hash functions are calculated based on the expected number of items and the desired false
    positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate the size of the bit array (m) using the formula:
        # m = -(n * ln(p)) / (ln(2) ^ 2)
        self.size = self._optimal_bit_array_size()

        # Calculate the number of hash functions (k) using the formula:
        # k = (m / n) * ln(2)
        self.num_hashes = self._optimal_number_of_hashes()

        # Initialize the bit array with zeros
        self.bit_array = [0] * self.size

    def _optimal_bit_array_size(self) -> int:
        """Calculate the optimal size of the bit array."""
        return int(-(self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2))

    def _optimal_number_of_hashes(self) -> int:
        """Calculate the optimal number of hash functions."""
        return max(1, int((self.size / self.expected_items) * math.log(2)))

    def _hashes(self, item: str) -> list:
        """Generate hash values for the given item using multiple hash functions."""
        hashes = []
        for i in range(self.num_hashes):
            hash_result = int(hashlib.md5((item + str(i)).encode()).hexdigest(), 16)
            hashes.append(hash_result % self.size)
        return hashes

    def add(self, item: str) -> None:
        """Add an item to the Bloom filter."""
        for h in self._hashes(item):
            self.bit_array[h] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is in the Bloom filter."""
        return all(self.bit_array[h] for h in self._hashes(item))

